// [VULN-N8-04] The model's output is treated as code.
//
// A Code node is a full JavaScript context in the n8n process: `require`, `process`,
// filesystem, and child_process are all reachable depending on the n8n version and its
// NODE_FUNCTION_ALLOW_EXTERNAL settings. `eval` on a model-authored string is therefore
// remote code execution inside the n8n server, not inside a sandbox -- and the n8n process
// holds every credential in the instance.
//
// The secure version is not 'sanitize the code'. It is: never evaluate model output.
// Parse it against a schema and read fields.

const raw = $input.first().json;
const text = String(raw.output ?? raw.text ?? '');

// Untrusted model output is being parsed as JSON with a permissive path.
let parsed;
try {
  parsed = JSON.parse(text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
} catch (err) {
  parsed = {};
}

// No schema validation, no allowlist of keys, no size bound on any field.
const facts = Array.isArray(parsed.facts) ? parsed.facts : [];

// Fields from the model are written into persistent state that later runs replay into the
// prompt -- see the 'Previous facts on record' interpolation in the agent node.
// This is memory poisoning with an extra hop (VULN-N8-10).
facts.push(`session said: ${text.slice(0, 300)}`);

return [{ json: { facts: facts.slice(-20), reply: text } }];
